The {\em symmetric local time at the point $x$\/} accumulated on the time interval $[0,t]$ by the semi-martingale $X$ satisfies a.s.
\begin{equation} \label{def:localtime}
    L_t^x(X)=\lim_{\epsilon\to 0}\frac{1}{2\epsilon}\int_0^t
    \ind{\{-\epsilon\leq X_s-x\leq \epsilon\}}d\langle X\rangle_s
\end{equation}
and if $x=0$ we denote $L_t^0(X)$ by $L_t(X)$.

\begin{equation} \label{def:localtime}
    L_t^x(X)=\lim_{\epsilon\to 0}\frac{1}{2\epsilon}\int_0^t
    \ind{\{-\epsilon\leq X_s-x\leq \epsilon\}}d\langle X\rangle_s
\end{equation}

\begin{equation} \label{eq:SBM}
X_t=X_0 + W_t+ \beta L_t^{r}(X)
\end{equation}

\begin{equation}
	\mu_\beta(\!\,\mathrm{d} x) := \left( (1+\beta) \ind{(0,\infty)}(x) + (1-\beta) \ind{(-\infty,0)}(x) \right)\! \,\mathrm{d} x =( 1+\mathrm{sgn}(x) \beta )  \,\mathrm{d} x,
\end{equation}

\begin{equation} \label{eq:SBM:density}
    p_\beta(t,x,y)
    =\frac{1}{\sqrt{2\pi t}}\exp\!\left(-\frac{(x-y)^2}{2t}\right)
    +\beta \mathrm{sgn}(y)\frac{1}{\sqrt{2\pi t}}\exp\!\left(-\frac{(|{x}|+|{y}|)^2}{2t}\right).
\end{equation}

\begin{equation} \label{eq:OSBM}
	X_t = X_0 + \int_0^t  \sigma(X_s) \,\mathrm{d} W_s + \beta L^r_t(X)  \quad t\geq 0 \quad \mathbb{P}\text{-a.s.}
\end{equation}

\begin{equation}
    \label{sigmaOBM}
    \sigma := \sigma_- \ind{(-\infty,r)} + \sigma_+ \ind{[r,+\infty)}




\end{equation}

\begin{equation} \label{eq:speedm}
	\mu_X(\!\,\mathrm{d} x) 
	= \frac{1+\mathrm{sgn}(x)\beta}{(\sigma(x))^2} \,\mathrm{d} x
	= \left( \frac{1-\beta}{\sigma_-^2} \ind{(-\infty,0)}(x) + \frac{1+\beta}{\sigma_+^2} \ind{[0,\infty)}(x) \right)\! \,\mathrm{d} x
\end{equation}

\begin{equation} \label{eq:densities:X}
	p_X(t,x,y)=\frac{1}{\sigma(y)} \, p_{\beta_\sigma}\Big(t, \frac{x}{\sigma(x)}, \frac{y}{\sigma(y)}\Big) 
\quad \text{ with } \quad 
{\beta_\sigma}:= \frac{(1+\beta)\sigma_- -(1-\beta)\sigma_+}{(1+\beta)\sigma_-+(1-\beta)\sigma_+}
\end{equation}

\begin{equation}
    \label{eq:OBM}
    X_t=X_0+\int_0^t \sigma(X_s)\,\mathrm{d} W_s, \quad t\geq 0,
