\begin{equation}	
\lambda_\sigma(\!\,\mathrm{d} x) := \frac1{(\sigma(x))^2} \,\mathrm{d} x 

\quad \text{ and } \quad
q_\sigma(t,x,y) =\frac{1}{\sigma(y)} \, p_{\beta_\sigma}\Big(t, \frac{x}{\sigma(x)}, \frac{y}{\sigma(y)}\Big)
\end{equation}

Given two measurable functions $f\colon \mathbb{R}^2 \to \mathbb{R}$ and $g\colon \mathbb{R} \to \mathbb{R}$, let
\begin{equation} \label{eq:muX}
	\bfF{f,g}(x) = \int_{-\infty}^{\infty} f(x,y) g(y) p_X(1,x,y) \,\mathrm{d} y \quad
\text{ and } \quad \bfF{f} := \bfF{f,1}
\ (\text{i.e.~}g\equiv 1).
\end{equation}

\begin{equation} \label{eq:muX}
	\bfF{f,g}(x) = \int_{-\infty}^{\infty} f(x,y) g(y) p_X(1,x,y) \,\mathrm{d} y \quad
\text{ and } \quad \bfF{f} := \bfF{f,1}
\ (\text{i.e.~}g\equiv 1).
\end{equation}

Note that, if $X$ denotes the solution with $r=0$, then
