 \label{prop:lmt:2:OSBM}
Let $f \colon \mathbb{R}^2 \to \mathbb{R}$ be a function satisfying Hypothesis~\ref{hp:OSBM:1} and let $X$ be the OSBM solution to~\eqref{eq:OSBM}. 

Then 
\begin{equation} \label{prop:lmt:2:OSBM:eq}
	\varepsilon_{n,\cdot}^{(r,f,X)} \convucp[n\to\infty] \langle \mu_X , \bfF f \rangle L^r_{\cdot}(X).
\end{equation}

\begin{equation} \label{prop:lmt:2:OSBM:eq}
	\varepsilon_{n,\cdot}^{(r,f,X)} \convucp[n\to\infty] \langle \mu_X , \bfF f \rangle L^r_{\cdot}(X).
\end{equation}

\begin{equation}
	\langle \mu_X , \bfF{f} \rangle 

	= \mathbb{E}\!\left[ f(X_0,X_1)|X_0 \sim \mu_X\right].
\end{equation}

More precisely, let $X^{(\theta)}$ denote the solution associated to the parameter $\theta \in \Theta$, then for all $t\in (0,\infty)$ it holds for all $\varepsilon \in (0,\infty)$ that 
\begin{equation} 
	\lim_{n\to\infty} \sup_{\theta \in \Theta} \mathbb{P}\left(  \sup_{s\in [0,t]} \left| \varepsilon_{n,s}^{(r,f,X^{(\theta)})} - \langle \mu_X , \bfF{f} \rangle L^r_{s}(X^{(\theta)})\right| \geq \varepsilon \right)
	= 0.
\end{equation}

\begin{equation} 
	\lim_{n\to\infty} \sup_{\theta \in \Theta} \mathbb{P}\left(  \sup_{s\in [0,t]} \left| \varepsilon_{n,s}^{(r,f,X^{(\theta)})} - \langle \mu_X , \bfF{f} \rangle L^r_{s}(X^{(\theta)})\right| \geq \varepsilon \right)
	= 0.
\end{equation}

