\mathbb{E}\!\left[\chi_k^n (Y_{k/n} - Y_{(k-1)/n})  | \mathcal{F}_{(k-1)/n}\right] 
	\\
	& = \frac1{\sqrt n}

\left(  n^{-\frac14} f_1(\sqrt{n} Y_{(k-1)/n}) + g_{n}(\sqrt{n} Y_{(k-1)/n}) + \langle \lambda_\sigma , \bfH h \rangle   n^{-\frac14} f_2(\sqrt{n} Y_{(k-1)/n})\right)



\end{split}
\end{equation}

\begin{equation}
\begin{split}
	f_1(x)& := \int_{-\infty}^\infty (h(x,y)+\bfG{h}(y)) (y-x) q_\sigma(1,x,y) \,\mathrm{d} y , 
	\ f_2(x):= x \Lm{1}{1}{x}, \ \text{and}
	\\
	g_n(x) & := n^{-\frac14} \int_{-\infty}^\infty \mathcal{Q}_{n,1,0}(y) (y-x) q_\sigma(1,x,y) \,\mathrm{d} y.
\end{split}	
\end{equation}

\begin{equation}
\begin{split}
	& n^{\frac34} \, \mathbb{E}\!\left[\chi_k^n (Y_{k/n} - Y_{(k-1)/n})  | \mathcal{F}_{(k-1)/n}\right] 
	\\
	& =  f_1(\sqrt{n} Y_{(k-1)/n}) +  \langle \lambda_\sigma , \bfH h \rangle f_2(\sqrt{n} Y_{(k-1)/n})
	- \Lm{ \mathbb{Id} }{1}{\sqrt{n} Y_{(k-1)/n}} )
	+ n^{1/4}g_n(\sqrt{n}Y_{(k-1)/n}).
\end{split}
\end{equation}

\begin{equation}
\begin{split} 
	|f_1(x)|  
	&
	\leq \bar h(x) \int_{-\infty}^{\infty}  e^{a |y-x|} |y-x| q_\sigma(1,x,y) \,\mathrm{d} y
	+ \sqrt{\sigma_-^2 \ind{\{\sigma_-\in\mathbb{R}\}} +\sigma_+^2 \ind{\{\sigma_+\in\mathbb{R}\}}} \left( |Q^\sigma_1 \bfG{h}^2 (x)| \right)^{\!1/2}.
\end{split}
\end{equation}

\begin{equation}
	|Q^\sigma_1 \bfG{h}^2 (x)| \leq K \frac{1}{1+|x/\sigma(x)|^{\gamma-1}} + K \frac1{\sqrt{2 \pi}} e^{-\frac{x^2}{2 (\sigma(x))^2 }} 
\leq 2 K^2 \frac{1}{(1+|x/\sigma(x)|^{\frac{\gamma-1}{2}})^2} .
\end{equation}

\begin{equation}
\begin{split} 
	f_2(x)  
	& = \left(\frac{2 \sigma_-\sigma_+}{\sigma_-+\sigma_+}\right)^{\! 2} \frac{x |x|}{\sigma(x)} \mathbb{E}\!\left[ \frac{L_1(W)}{\sigma(W_1)} \right] 
	\int_0^1  \frac{\sqrt{1-s}}{\sqrt{2\pi} s^\frac32} e^{-\frac{x^2}{2 (\sigma(x))^2 s}} 
	\! \,\mathrm{d} s
	\\
	& = \left(\frac{2 \sigma_-\sigma_+}{\sigma_-+\sigma_+}\right)^{\! 2} \frac{x |x|}{\sigma(x)} \mathbb{E}\!\left[ \frac{L_1(W)}{\sigma(W_1)} \right] 
	\int_{\frac{x^2}{(\sigma(x))^2}}^\infty  \frac1{\sqrt{2\pi}}
 \sqrt{\frac{(\sigma(x))^2}{x^2}-\frac1r} e^{-\frac{r}{2}} 
	\frac1{\sqrt{r}}\! \,\mathrm{d} r \ \ind{\{\sigma(x)\in \mathbb{R}\}}
	\\
	& \leq \left(\frac{2 \sigma_-\sigma_+}{\sigma_-+\sigma_+}\right)^{\! 2} \frac{|x| \mathbb{E}\!\left[L_1(W)\right] }{\min\{\sigma_-,\sigma_+\}}
	\int_{\frac{x^2}{(\sigma(x))^2}}^\infty  \frac1{\sqrt{2\pi}}
  e^{-\frac{r}{2}} 
	\frac1{\sqrt{r}}\! \,\mathrm{d} r \ \ind{\{\sigma(x)\in \mathbb{R}\}}
	\leq K e^{-\frac{x^2}{4(\sigma(x))^2}} \in \Lgb{0}.
\end{split}
\end{equation}

\begin{equation}
\begin{split}
	|g_n(x)|^2 
	& \leq n^{-1/2} \left( \int_{-\infty}^{\infty} (\mathcal{Q}_{n,1,0}(y))^2 q_\sigma (1,x,y) \,\mathrm{d} y\right) \left(\int_{-\infty}^{\infty} (y-x)^2 q_\sigma(1,x,y) \,\mathrm{d} y\right).
\end{split}
\end{equation}

\begin{equation}
\begin{split}
	& \mathbb{E}\!\left[ |\chi_k^n|^2 \ind{\{|\chi_k^n|\geq  \varepsilon \}}| \mathcal{F}_{(k-1)/n}\right] 
	 \leq 





\mathbb{E}\!\left[ |\chi_k^n|^{5} | \mathcal{F}_{(k-1)/n}\right]  \varepsilon^{-3} .
\end{split}
\end{equation}

\begin{equation}
\begin{split}
	 & \mathbb{E}\!\left[ |\chi_k^n|^{5} | \mathcal{F}_{(k-1)/n}\right] 
	  \leq  4^{4} n^{-\frac{5}{4}} K^{5} \Big(  \mathbb{E}\!\left[ e^{5 a \sqrt n | Y_{k/n} - Y_{(k-1)/n}|}  | \mathcal{F}_{(k-1)/n}\right]  
	\\
	& \quad \qquad 	+ \mathbb{E}\!\left[  \left(\sqrt{n}|L_{k/n}(Y) - L_{(k-1)/n}(Y)| \right)^{5} | \mathcal{F}_{(k-1)/n}\right] 
	+ (\log n)^{5} \Big).
\end{split}
\end{equation}

\begin{equation}
\begin{split}
	& \mathbb{E}\!\left[  \left(\sqrt{n}|L_{k/n}(Y) - L_{(k-1)/n}(Y)| \right)^{5} | \mathcal{F}_{(k-1)/n}\right] 
	= \Lm {1}{5}{\sqrt{n}Y_{(k-1)/n}} 
	\\
	& \leq K_1 \int_0^1 \frac{(1-t)^{\frac52}}{\sqrt{2 \pi} t^{\frac32}}  \frac{\sqrt{n}|Y_{(k-1)/n}|}{\sigma(Y_{(k-1)/n})} e^{-\frac{n (Y_{(k-1)/n})^2}{2 (\sigma(Y_{(k-1)/n})) t } } \,\mathrm{d} t
\leq K_2.
\end{split}
\end{equation}

We conclude that there exists a constant $K\in (0,\infty)$ such that
\begin{equation}
\begin{split}
	& \sum_{k=1}^n \mathbb{E}\!\left[ |\chi_k^n|^2 \ind{\{|\chi_k^n|\geq  \varepsilon \}}| \mathcal{F}_{(k-1)/n}\right] 


	\leq n K n^{-\frac54} \log(n)  \varepsilon^{-3} \xrightarrow[n\to\infty]{} 0.
\end{split}
\end{equation}

\begin{equation}
\begin{split}
	& \sum_{k=1}^n \mathbb{E}\!\left[ |\chi_k^n|^2 \ind{\{|\chi_k^n|\geq  \varepsilon \}}| \mathcal{F}_{(k-1)/n}\right] 


	\leq n K n^{-\frac54} \log(n)  \varepsilon^{-3} \xrightarrow[n\to\infty]{} 0.
\end{split}
\end{equation}

